import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { AdminService } from '../../core/admin.service';
import { CLASS_CATEGORIES } from '../../core/class.categories';

interface FieldDef { key: string; label: string; type?: 'text' | 'number' | 'datetime-local' | 'date' | 'select' | 'checkbox' | 'textarea' | 'image'; options?: string[]; }
interface ResourceDef {
  key: string;           // API path segment
  title: string;
  columns: string[];     // fields shown in table
  fields: FieldDef[];    // fields shown in the add/edit form
}

const RESOURCES: ResourceDef[] = [
  {
    key: 'users', title: 'Users',
    columns: ['id', 'name', 'email', 'phone', 'role', 'level', 'status', 'preferred_category', 'email_verified_at', 'phone_verified_at'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'email', label: 'Email' },
      { key: 'phone', label: 'Phone' },
      { key: 'role', label: 'Role', type: 'select', options: ['user', 'admin'] },
      { key: 'level', label: 'Level', type: 'select', options: ['Initiation', 'Debutant', 'Intermediaire', 'Avancee', 'Expert'] },
      { key: 'status', label: 'Status', type: 'select', options: ['pending_category', 'pending_approval', 'approved', 'rejected'] },
      { key: 'preferred_category', label: 'Preferred Category', type: 'select', options: ['', ...CLASS_CATEGORIES] },
      { key: 'avatar', label: 'Avatar', type: 'image' },
    ],
  },
  {
    key: 'trainers', title: 'Trainers',
    columns: ['id', 'name', 'specialty'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'specialty', label: 'Specialty' },
      { key: 'bio', label: 'Bio', type: 'textarea' },
      { key: 'avatar', label: 'Avatar', type: 'image' },
    ],
  },
  {
    key: 'classes', title: 'Classes',
    columns: ['id', 'name', 'trainer_name', 'category', 'location', 'level', 'starts_at', 'ends_at', 'capacity', 'spots_left'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'trainer_id', label: 'Trainer ID', type: 'number' },
      { key: 'category', label: 'Category', type: 'select', options: ['', ...CLASS_CATEGORIES] },
      { key: 'level', label: 'Level (Pilates)', type: 'select', options: ['', 'Initiation', 'Debutant', 'Intermediaire', 'Avancee', 'Expert'] },
      { key: 'location', label: 'Location' },
      { key: 'starts_at', label: 'Starts At', type: 'datetime-local' },
      { key: 'ends_at', label: 'Ends At', type: 'datetime-local' },
      { key: 'capacity', label: 'Capacity', type: 'number' },
    ],
  },
  {
    key: 'class-categories', title: 'Class Categories',
    columns: ['id', 'name', 'is_active', 'sort_order'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'is_active', label: 'Active', type: 'checkbox' },
      { key: 'sort_order', label: 'Sort Order', type: 'number' },
    ],
  },
  {
    key: 'plans', title: 'Membership Plans',
    columns: ['id', 'name', 'price', 'classes_per_month', 'duration_months', 'category', 'is_active'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'price', label: 'Price', type: 'number' },
      { key: 'classes_per_month', label: 'Classes/Month (blank=unlimited)', type: 'number' },
      { key: 'duration_months', label: 'Duration (months)', type: 'number' },
      { key: 'category', label: 'Category', type: 'select', options: [] },
      { key: 'is_active', label: 'Active', type: 'checkbox' },
    ],
  },
  {
    key: 'memberships', title: 'Memberships',
    columns: ['id', 'user_name', 'plan_name', 'status', 'classes_used_this_month', 'started_at', 'renews_at'],
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['pending', 'active', 'expired', 'cancelled'] },
      { key: 'plan_id', label: 'Plan ID', type: 'number' },
      { key: 'classes_used_this_month', label: 'Classes Used This Month', type: 'number' },
      { key: 'started_at', label: 'Started At', type: 'date' },
      { key: 'renews_at', label: 'Renews At', type: 'date' },
    ],
  },
  {
    key: 'bookings', title: 'Bookings',
    columns: ['id', 'user_name', 'class_name', 'starts_at', 'status'],
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['booked', 'cancelled', 'attended', 'no_show'] },
    ],
  },
  {
    key: 'workouts', title: 'Workouts',
    columns: ['id', 'user_name', 'type', 'duration_minutes', 'calories_burned', 'performed_at'],
    fields: [
      { key: 'user_id', label: 'User ID', type: 'number' },
      { key: 'class_id', label: 'Class ID (optional)', type: 'number' },
      { key: 'type', label: 'Type' },
      { key: 'duration_minutes', label: 'Duration (min)', type: 'number' },
      { key: 'calories_burned', label: 'Calories Burned', type: 'number' },
      { key: 'performed_at', label: 'Performed At', type: 'date' },
    ],
  },
  {
    key: 'diet-logs', title: 'Diet Logs',
    columns: ['id', 'user_name', 'meal_type', 'description', 'calories', 'logged_at'],
    fields: [
      { key: 'user_id', label: 'User ID', type: 'number' },
      { key: 'meal_type', label: 'Meal Type', type: 'select', options: ['breakfast', 'lunch', 'dinner', 'snack'] },
      { key: 'description', label: 'Description' },
      { key: 'calories', label: 'Calories', type: 'number' },
      { key: 'logged_at', label: 'Logged At', type: 'date' },
    ],
  },
  {
    key: 'products', title: 'Store',
    columns: ['id', 'name', 'category', 'price', 'stock', 'is_active'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'category', label: 'Category', type: 'select', options: ['supplements', 'apparel', 'accessories'] },
      { key: 'description', label: 'Description', type: 'textarea' },
      { key: 'price', label: 'Price', type: 'number' },
      { key: 'stock', label: 'Stock', type: 'number' },
      { key: 'image', label: 'Image', type: 'image' },
      { key: 'is_active', label: 'Active', type: 'checkbox' },
    ],
  },
  {
    key: 'posters', title: 'Posters',
    columns: ['id', 'username', 'location', 'text', 'created_at'],
    fields: [
      { key: 'username', label: 'Username' },
      { key: 'location', label: 'Location' },
      { key: 'text', label: 'Description', type: 'textarea' },
      { key: 'image', label: 'Image (optional)', type: 'image' },
    ],
  },
  {
    key: 'notifications', title: 'Notifications',
    columns: ['id', 'user_id', 'message', 'is_read', 'created_at'],
    fields: [
      { key: 'user_id', label: 'User ID', type: 'number' },
      { key: 'message', label: 'Message', type: 'textarea' },
      { key: 'is_read', label: 'Read', type: 'checkbox' },
    ],
  },
];


// ---- Dashboard UI config (sidebar groups, icons) ----
const ICONS: Record<string, string> = {
  overview: 'M3 3h7v9H3zM14 3h7v5h-7zM14 12h7v9h-7zM3 16h7v5H3z',
  users: 'M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',
  trainers: 'M12 15a7 7 0 1 0 0-14 7 7 0 0 0 0 14zM8.21 13.89L7 23l5-3 5 3-1.21-9.12',
  classes: 'M19 4H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2zM16 2v4M8 2v4M3 10h18',
  'class-categories': 'M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82zM7 7h.01',
  plans: 'M21 4H3a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h18a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2zM1 10h22',
  memberships: 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM16 11l2 2 4-4',
  bookings: 'M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2M9 2h6v4H9zM9 14l2 2 4-4',
  workouts: 'M22 12h-4l-3 9L9 3l-3 9H2',
  'diet-logs': 'M18 8h1a4 4 0 0 1 0 8h-1M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8zM6 1v3M10 1v3M14 1v3',
  products: 'M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4zM3 6h18M16 10a4 4 0 0 1-8 0',
  posters: 'M19 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2zM8.5 10a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3zM21 15l-5-5L5 21',
  notifications: 'M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9M13.73 21a2 2 0 0 1-3.46 0',
  approvals: 'M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M8.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM17 11l2 2 4-4',
  send: 'M22 2L11 13M22 2l-7 20-4-9-9-4z',
  search: 'M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16zM21 21l-4.35-4.35',
  plus: 'M12 5v14M5 12h14',
  menu: 'M3 12h18M3 6h18M3 18h18',
  back: 'M19 12H5M12 19l-7-7 7-7',
  edit: 'M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4z',
  trash: 'M3 6h18M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6M10 11v6M14 11v6M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2',
  close: 'M18 6L6 18M6 6l12 12',
  check: 'M20 6L9 17l-5-5',
  chevL: 'M15 18l-6-6 6-6',
  chevR: 'M9 18l6-6-6-6',
  inbox: 'M22 12h-6l-2 3h-4l-2-3H2M5.45 5.11L2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z',
};

const NAV_GROUPS: { label: string; items: string[] }[] = [
  { label: 'People',   items: ['users', 'trainers', 'memberships'] },
  { label: 'Training', items: ['classes', 'class-categories', 'bookings', 'workouts', 'diet-logs'] },
  { label: 'Business', items: ['plans', 'products', 'posters'] },
  { label: 'Messaging', items: ['notifications'] },
];

const STAT_CARDS = [
  { key: 'users', label: 'Total users', icon: 'users', tone: 'gold', go: 'users' },
  { key: 'trainers', label: 'Trainers', icon: 'trainers', tone: 'green', go: 'trainers' },
  { key: 'upcoming_classes', label: 'Upcoming classes', icon: 'classes', tone: 'blue', go: 'classes' },
  { key: 'active_memberships', label: 'Active memberships', icon: 'memberships', tone: 'purple', go: 'memberships' },
  { key: 'bookings_today', label: 'Bookings today', icon: 'bookings', tone: 'orange', go: 'bookings' },
];

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './admin.component.html',
  styleUrl: './admin.component.css',
})
export class AdminComponent implements OnInit {
  resources = RESOURCES;
  icons = ICONS;
  statCards = STAT_CARDS;
  navGroups = NAV_GROUPS.map(g => ({
    label: g.label,
    items: g.items.map(k => RESOURCES.find(r => r.key === k)!).filter(Boolean),
  }));
  active: ResourceDef = RESOURCES[0];

  // table UX
  search = '';
  page = 1;
  pageSize = 10;
  sidebarOpen = false;

  // overview data
  recentBookings: any[] = [];
  bookingsByStatus: { label: string; count: number; pct: number; tone: string }[] = [];
  usersByStatus: { label: string; count: number; pct: number; tone: string }[] = [];
  overviewLoading = false;
  today = new Date();
  rows: any[] = [];
  loading = false;
  error = '';

  showForm = false;
  editingId: number | null = null;
  formModel: any = {};

  stats: any = null;

  // CHANGED — pending-account approvals
  activeSection: 'overview' | 'resource' | 'approvals' | 'send' = 'overview';
  notifMessage = '';
  notifAudience: 'all' | 'selected' = 'all';
  notifUsers: any[] = [];
  notifSelected = new Set<number>();
  notifSending = false;
  notifInfo = '';
  pendingApprovals: any[] = [];
  approvalsLoading = false;

  constructor(private admin: AdminService) {}

  async ngOnInit() {
    this.stats = await this.admin.stats().catch(() => null);
    await this.loadCategories();
    await this.showOverview();
    this.admin.pendingApprovals().then(r => this.pendingCount = r.length).catch(() => {});
  }

  pendingCount = 0;

  // ---------- Overview ----------
  async showOverview() {
    this.activeSection = 'overview';
    this.showForm = false;
    this.error = '';
    this.sidebarOpen = false;
    this.overviewLoading = true;
    try {
      const [stats, users, bookings, pending] = await Promise.all([
        this.admin.stats().catch(() => this.stats),
        this.admin.list('users').catch(() => [] as any[]),
        this.admin.list('bookings').catch(() => [] as any[]),
        this.admin.pendingApprovals().catch(() => [] as any[]),
      ]);
      this.stats = stats;
      this.pendingApprovals = pending;
      this.pendingCount = pending.length;
      this.recentBookings = [...bookings]
        .sort((a, b) => String(b.starts_at).localeCompare(String(a.starts_at)))
        .slice(0, 6);
      this.bookingsByStatus = this.distribution(bookings, 'status');
      this.usersByStatus = this.distribution(users.filter((u: any) => u.role !== 'admin'), 'status');
    } finally {
      this.overviewLoading = false;
    }
  }

  private distribution(list: any[], key: string) {
    const counts = new Map<string, number>();
    for (const r of list) {
      const k = String(r[key] ?? 'unknown');
      counts.set(k, (counts.get(k) || 0) + 1);
    }
    const total = list.length || 1;
    return [...counts.entries()]
      .sort((a, b) => b[1] - a[1])
      .map(([label, count]) => ({ label: this.pretty(label), count, pct: Math.round((count / total) * 100), tone: this.tone(label) }));
  }

  go(key: string) {
    const r = this.resources.find(x => x.key === key);
    if (r) this.select(r);
  }

  // ---------- Table helpers ----------
  get filteredRows(): any[] {
    const q = this.search.trim().toLowerCase();
    if (!q) return this.rows;
    return this.rows.filter(r => this.active.columns.some(c => String(r[c] ?? '').toLowerCase().includes(q)));
  }
  get totalPages(): number { return Math.max(1, Math.ceil(this.filteredRows.length / this.pageSize)); }
  get pagedRows(): any[] {
    const start = (this.page - 1) * this.pageSize;
    return this.filteredRows.slice(start, start + this.pageSize);
  }
  get rangeLabel(): string {
    const n = this.filteredRows.length;
    if (!n) return '0 results';
    const a = (this.page - 1) * this.pageSize + 1;
    return `${a}–${Math.min(n, a + this.pageSize - 1)} of ${n}`;
  }
  onSearch() { this.page = 1; }
  prevPage() { if (this.page > 1) this.page--; }
  nextPage() { if (this.page < this.totalPages) this.page++; }

  pretty(v: string): string {
    const t = String(v).replace(/_/g, ' ').trim();
    return t.charAt(0).toUpperCase() + t.slice(1);
  }
  colLabel(c: string): string {
    if (c === 'id') return 'ID';
    return this.pretty(c.replace(/_at$/, '').replace(/_id$/, ' ID'));
  }
  cellKind(c: string): 'avatar' | 'badge' | 'bool' | 'date' | 'money' | 'verified' | 'text' {
    if (['name', 'user_name', 'username'].includes(c)) return 'avatar';
    if (['status', 'role', 'level'].includes(c)) return 'badge';
    if (['is_active', 'is_read'].includes(c)) return 'bool';
    if (c === 'email_verified_at' || c === 'phone_verified_at') return 'verified';
    if (c.endsWith('_at')) return 'date';
    if (c === 'price') return 'money';
    return 'text';
  }
  tone(v: any): string {
    const s = String(v ?? '').toLowerCase();
    if (['approved', 'active', 'attended', '1', 'true', 'user', 'verified'].includes(s)) return 'green';
    if (['pending', 'pending_approval', 'pending_category'].includes(s)) return 'amber';
    if (['rejected', 'cancelled', 'expired', 'no_show', '0', 'false'].includes(s)) return 'red';
    if (['booked'].includes(s)) return 'blue';
    if (['admin', 'expert'].includes(s)) return 'purple';
    return 'gray';
  }
  initials(name: any): string {
    const parts = String(name ?? '?').trim().split(/\s+/).slice(0, 2);
    return parts.map(p => p.charAt(0).toUpperCase()).join('') || '?';
  }
  hue(name: any): number {
    let h = 0;
    for (const ch of String(name ?? '')) h = (h * 31 + ch.charCodeAt(0)) % 360;
    return h;
  }
  get sectionTitle(): string {
    switch (this.activeSection) {
      case 'overview': return 'Dashboard';
      case 'approvals': return 'Pending approvals';
      case 'send': return 'Send notification';
      default: return this.active.title;
    }
  }

  // Category dropdowns are built from the class-categories table (admin can add/delete freely)
  async loadCategories() {
    try {
      const cats: any[] = await this.admin.list('class-categories');
      const names = cats.filter(c => c.is_active !== 0 && c.is_active !== false).map(c => c.name);
      for (const r of this.resources) {
        for (const f of r.fields) {
          if ((r.key === 'users' && f.key === 'preferred_category') || (r.key === 'classes' && f.key === 'category')) {
            f.options = ['', ...names];
          } else if (r.key === 'plans' && f.key === 'category') {
            f.options = names;
          }
        }
      }
    } catch {}
  }

  async select(res: ResourceDef) {
    this.activeSection = 'resource'; // CHANGED
    this.active = res;
    this.search = '';
    this.page = 1;
    this.sidebarOpen = false;
    this.showForm = false;
    this.error = '';
    this.loading = true;
    try {
      this.rows = await this.admin.list(res.key);
    } catch (e: any) {
      this.error = e?.error?.error || 'Failed to load data';
      this.rows = [];
    } finally {
      this.loading = false;
    }
  }

  openCreate() {
    this.editingId = null;
    this.formModel = {};
    this.showForm = true;
  }

  openEdit(row: any) {
    this.editingId = row.id;
    this.formModel = { ...row };
    for (const f of this.active.fields) {
      const v = this.formModel[f.key];
      if (typeof v === 'string' && v) {
        if (f.type === 'date') this.formModel[f.key] = v.slice(0, 10);
        else if (f.type === 'datetime-local') this.formModel[f.key] = v.replace(' ', 'T').slice(0, 16);
      }
    }
    this.showForm = true;
  }

  cancelForm() {
    this.showForm = false;
    this.editingId = null;
  }

  onFileChange(event: Event, key: string) {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (file) this.formModel[key] = file;
  }

  async save() {
    try {
      if (this.editingId) {
        await this.admin.update(this.active.key, this.editingId, this.formModel);
      } else {
        await this.admin.create(this.active.key, this.formModel);
      }
      this.showForm = false;
      if (this.active.key === 'class-categories') await this.loadCategories();
      await this.select(this.active);
    } catch (e: any) {
      this.error = e?.error?.error || 'Save failed';
    }
  }

  async remove(row: any) {
    if (!confirm(`Delete this ${this.active.title.slice(0, -1)}?`)) return;
    try {
      await this.admin.remove(this.active.key, row.id);
      if (this.active.key === 'class-categories') await this.loadCategories();
      await this.select(this.active);
    } catch (e: any) {
      this.error = e?.error?.error || 'Delete failed';
    }
  }

  // CHANGED — pending-account approvals
  async showApprovals() {
    this.activeSection = 'approvals';
    this.sidebarOpen = false;
    this.showForm = false;
    this.error = '';
    this.approvalsLoading = true;
    try {
      this.pendingApprovals = await this.admin.pendingApprovals();
      this.pendingCount = this.pendingApprovals.length;
    } catch (e: any) {
      this.error = e?.error?.error || 'Failed to load pending approvals';
      this.pendingApprovals = [];
    } finally {
      this.approvalsLoading = false;
    }
  }

  async showSend() {
    this.activeSection = 'send';
    this.sidebarOpen = false;
    this.showForm = false;
    this.error = '';
    this.notifInfo = '';
    try {
      this.notifUsers = (await this.admin.list('users')).filter((u: any) => u.role !== 'admin');
    } catch (e: any) {
      this.error = e?.error?.error || 'Failed to load users';
    }
  }

  toggleNotifUser(id: number) {
    this.notifSelected.has(id) ? this.notifSelected.delete(id) : this.notifSelected.add(id);
  }

  async sendNotification() {
    const message = this.notifMessage.trim();
    const ids = this.notifAudience === 'all' ? this.notifUsers.map(u => u.id) : [...this.notifSelected];
    this.error = ''; this.notifInfo = '';
    if (!message) { this.error = 'Message is required'; return; }
    if (!ids.length) { this.error = 'No recipients selected'; return; }
    this.notifSending = true;
    try {
      for (let i = 0; i < ids.length; i += 10) {
        await Promise.all(ids.slice(i, i + 10).map(id => this.admin.create('notifications', { user_id: id, message })));
      }
      this.notifInfo = `Sent to ${ids.length} user(s).`;
      this.notifMessage = '';
      this.notifSelected.clear();
    } catch (e: any) {
      this.error = e?.error?.error || 'Sending failed';
    } finally {
      this.notifSending = false;
    }
  }

  private async refreshApprovalsView() {
    if (this.activeSection === 'overview') await this.showOverview();
    else await this.showApprovals();
  }

  async approveUser(row: any) {
    try {
      await this.admin.approveUser(row.id);
      await this.refreshApprovalsView();
    } catch (e: any) {
      this.error = e?.error?.error || 'Approval failed';
    }
  }

  async rejectUser(row: any) {
    if (!confirm(`Reject ${row.name}'s account request?`)) return;
    try {
      await this.admin.rejectUser(row.id);
      await this.refreshApprovalsView();
    } catch (e: any) {
      this.error = e?.error?.error || 'Rejection failed';
    }
  }
}
<div class="adm-shell">

  <!-- ============ SIDEBAR ============ -->
  <div class="adm-scrim" *ngIf="sidebarOpen" (click)="sidebarOpen = false"></div>
  <aside class="adm-nav" [class.adm-nav-open]="sidebarOpen">
    <div class="adm-brand">
      <div class="adm-brand-mark">E</div>
      <div>
        <div class="adm-brand-name">EOS Fitness</div>
        <div class="adm-brand-sub">Admin console</div>
      </div>
    </div>

    <nav class="adm-nav-scroll">
      <button class="adm-nav-btn" [class.adm-active]="activeSection === 'overview'" (click)="showOverview()">
        <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['overview']"/></svg>
        <span>Dashboard</span>
      </button>

      <div class="adm-nav-group" *ngFor="let g of navGroups">
        <div class="adm-nav-label">{{ g.label }}</div>
        <button *ngFor="let r of g.items" class="adm-nav-btn"
                [class.adm-active]="r.key === active.key && activeSection === 'resource'"
                (click)="select(r)">
          <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons[r.key]"/></svg>
          <span>{{ r.title }}</span>
        </button>
      </div>

      <div class="adm-nav-group">
        <div class="adm-nav-label">Requests</div>
        <button class="adm-nav-btn" [class.adm-active]="activeSection === 'approvals'" (click)="showApprovals()">
          <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['approvals']"/></svg>
          <span>Approvals</span>
          <span class="adm-pill" *ngIf="pendingCount">{{ pendingCount }}</span>
        </button>
        <button class="adm-nav-btn" [class.adm-active]="activeSection === 'send'" (click)="showSend()">
          <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['send']"/></svg>
          <span>Send notification</span>
        </button>
      </div>
    </nav>

    <a routerLink="/app" class="adm-back-link">
      <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['back']"/></svg>
      Back to app
    </a>
  </aside>

  <!-- ============ MAIN ============ -->
  <div class="adm-content">

    <header class="adm-topbar">
      <button class="adm-icon-btn adm-burger" (click)="sidebarOpen = !sidebarOpen" aria-label="Menu">
        <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['menu']"/></svg>
      </button>
      <div class="adm-search" *ngIf="activeSection === 'resource'">
        <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['search']"/></svg>
        <input type="text" placeholder="Search {{ active.title.toLowerCase() }}" [(ngModel)]="search" name="search" (ngModelChange)="onSearch()" />
      </div>
      <time class="adm-date">{{ today | date:'EEE d MMM y' }}</time>
    </header>

    <main class="adm-main">
      <p class="adm-error" *ngIf="error">{{ error }}</p>

      <!-- ===== OVERVIEW ===== -->
      <ng-container *ngIf="activeSection === 'overview'">
        <div class="adm-page-head">
          <h1 class="adm-headline">{{ stats ? headline : 'Loading today’s numbers' }}</h1>
          <div class="adm-head-actions">
            <button class="adm-btn adm-btn-ghost" (click)="showSend()">
              <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['send']"/></svg> Send notification
            </button>
            <button class="adm-btn adm-btn-primary" (click)="go('classes'); openCreate()">
              <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['plus']"/></svg> New class
            </button>
          </div>
        </div>

        <!-- one large figure, the rest as a ruled list -->
        <section class="adm-hero">
          <button class="adm-hero-main" (click)="go('bookings')">
            <span class="adm-hero-label">Bookings today</span>
            <span class="adm-hero-num">{{ stats?.bookings_today ?? '–' }}</span>
            <span class="adm-hero-sub">Open the bookings table →</span>
          </button>
          <ul class="adm-ruled">
            <li *ngFor="let c of sideStats" (click)="go(c.go)">
              <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons[c.icon]"/></svg>
              <span>{{ c.label }}</span>
              <b>{{ stats ? (stats[c.key] ?? 0) : '–' }}</b>
            </li>
          </ul>
        </section>

        <div class="adm-grid-2">
          <!-- Pending approvals -->
          <section class="adm-card">
            <div class="adm-card-head">
              <div>
                <h3>Pending approvals</h3>
                <p class="adm-muted">New sign-ups waiting for your review</p>
              </div>
              <button class="adm-link" (click)="showApprovals()">View all</button>
            </div>
            <ul class="adm-list" *ngIf="pendingApprovals.length">
              <li *ngFor="let row of pendingApprovals.slice(0, 5)">
                <div class="adm-avatar" [style.--h]="hue(row.name)">{{ initials(row.name) }}</div>
                <div class="adm-list-main">
                  <strong>{{ row.name }}</strong>
                  <small>{{ row.plan_name }} · {{ row.price }} TND</small>
                </div>
                <div class="adm-list-actions">
                  <button class="adm-btn-sm adm-btn-success" (click)="approveUser(row)">Approve</button>
                  <button class="adm-btn-sm adm-btn-danger-o" (click)="rejectUser(row)">Reject</button>
                </div>
              </li>
            </ul>
            <div class="adm-empty adm-empty-sm" *ngIf="!pendingApprovals.length">
              <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['check']"/></svg>
              <p>You're all caught up — no pending requests.</p>
            </div>
          </section>

          <!-- Distributions -->
          <section class="adm-card">
            <div class="adm-card-head">
              <div>
                <h3>Activity breakdown</h3>
                <p class="adm-muted">Live distribution from your data</p>
              </div>
            </div>

            <div class="adm-dist">
              <h4>Members by status</h4>
              <div class="adm-bar-stack" *ngIf="usersByStatus.length">
                <span *ngFor="let d of usersByStatus" [attr.data-tone]="d.tone" [style.flex]="d.count" [title]="d.label + ': ' + d.count"></span>
              </div>
              <ul class="adm-legend">
                <li *ngFor="let d of usersByStatus"><i [attr.data-tone]="d.tone"></i>{{ d.label }}<b>{{ d.count }}</b></li>
                <li *ngIf="!usersByStatus.length" class="adm-muted">No data yet</li>
              </ul>
            </div>

            <div class="adm-dist">
              <h4>Bookings by status</h4>
              <div class="adm-bar-stack" *ngIf="bookingsByStatus.length">
                <span *ngFor="let d of bookingsByStatus" [attr.data-tone]="d.tone" [style.flex]="d.count" [title]="d.label + ': ' + d.count"></span>
              </div>
              <ul class="adm-legend">
                <li *ngFor="let d of bookingsByStatus"><i [attr.data-tone]="d.tone"></i>{{ d.label }}<b>{{ d.count }}</b></li>
                <li *ngIf="!bookingsByStatus.length" class="adm-muted">No data yet</li>
              </ul>
            </div>
          </section>
        </div>

        <!-- Recent bookings -->
        <section class="adm-card adm-card-flush">
          <div class="adm-card-head adm-pad">
            <div>
              <h3>Recent bookings</h3>
              <p class="adm-muted">Latest class reservations</p>
            </div>
            <button class="adm-link" (click)="go('bookings')">View all</button>
          </div>
          <div class="adm-table-wrap" *ngIf="recentBookings.length">
            <table class="adm-table">
              <thead><tr><th>Member</th><th>Class</th><th>Starts</th><th>Status</th></tr></thead>
              <tbody>
                <tr *ngFor="let b of recentBookings">
                  <td>
                    <div class="adm-cell-user">
                      <div class="adm-avatar adm-avatar-sm" [style.--h]="hue(b.user_name)">{{ initials(b.user_name) }}</div>
                      <span>{{ b.user_name }}</span>
                    </div>
                  </td>
                  <td>{{ b.class_name }}</td>
                  <td class="adm-nowrap">{{ b.starts_at | date:'MMM d, HH:mm' }}</td>
                  <td><span class="adm-badge" [attr.data-tone]="tone(b.status)">{{ pretty(b.status) }}</span></td>
                </tr>
              </tbody>
            </table>
          </div>
          <div class="adm-empty adm-empty-sm" *ngIf="!recentBookings.length">
            <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['inbox']"/></svg>
            <p>No bookings yet.</p>
          </div>
        </section>
      </ng-container>

      <!-- ===== RESOURCE TABLES ===== -->
      <ng-container *ngIf="activeSection === 'resource'">
        <div class="adm-page-head">
          <div>
            <h1>{{ active.title }}</h1>
            <p class="adm-muted">{{ rows.length }} total record{{ rows.length === 1 ? '' : 's' }}</p>
          </div>
          <div class="adm-head-actions">
            <button class="adm-btn adm-btn-primary" (click)="openCreate()">
              <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['plus']"/></svg> Add {{ active.title.slice(0, -1).toLowerCase() }}
            </button>
          </div>
        </div>

        <section class="adm-card adm-card-flush">
          <div class="adm-loading" *ngIf="loading"><span class="adm-spinner"></span> Loading…</div>

          <div class="adm-table-wrap" *ngIf="!loading && pagedRows.length">
            <table class="adm-table">
              <thead>
                <tr>
                  <th *ngFor="let c of active.columns">{{ colLabel(c) }}</th>
                  <th class="adm-th-actions"></th>
                </tr>
              </thead>
              <tbody>
                <tr *ngFor="let row of pagedRows">
                  <td *ngFor="let c of active.columns" [ngSwitch]="cellKind(c)">
                    <div *ngSwitchCase="'avatar'" class="adm-cell-user">
                      <div class="adm-avatar adm-avatar-sm" [style.--h]="hue(row[c])">{{ initials(row[c]) }}
                        <img *ngIf="row.avatar_url" [src]="row.avatar_url" alt="" (error)="$any($event.target).remove()" />
                      </div>
                      <span>{{ row[c] }}</span>
                    </div>
                    <span *ngSwitchCase="'badge'" class="adm-badge" [attr.data-tone]="tone(row[c])">{{ pretty(row[c] ?? '—') }}</span>
                    <span *ngSwitchCase="'bool'" class="adm-badge" [attr.data-tone]="row[c] ? 'green' : 'gray'">{{ row[c] ? 'Active' : 'Inactive' }}</span>
                    <span *ngSwitchCase="'verified'" class="adm-badge" [attr.data-tone]="row[c] ? 'green' : 'gray'">{{ row[c] ? 'Verified' : 'No' }}</span>
                    <span *ngSwitchCase="'date'" class="adm-nowrap">{{ row[c] ? (row[c] | date:'MMM d, y, HH:mm') : '—' }}</span>
                    <span *ngSwitchCase="'money'" class="adm-nowrap"><b>{{ row[c] }}</b> TND</span>
                    <span *ngSwitchDefault class="adm-clip" [class.adm-muted]="c === 'id'">{{ row[c] ?? '—' }}</span>
                  </td>
                  <td class="adm-row-actions">
                    <button class="adm-icon-btn adm-icon-btn-sm" (click)="openEdit(row)" title="Edit">
                      <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['edit']"/></svg>
                    </button>
                    <button class="adm-icon-btn adm-icon-btn-sm adm-icon-danger" (click)="remove(row)" title="Delete">
                      <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['trash']"/></svg>
                    </button>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <div class="adm-empty" *ngIf="!loading && !pagedRows.length">
            <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['inbox']"/></svg>
            <h4>{{ search ? 'No matches found' : 'No records yet' }}</h4>
            <p class="adm-muted">{{ search ? 'Try a different search term.' : 'Click “Add” to create the first one.' }}</p>
          </div>

          <footer class="adm-pager" *ngIf="!loading && filteredRows.length">
            <span class="adm-muted">{{ rangeLabel }}</span>
            <div class="adm-pager-ctl">
              <button class="adm-icon-btn adm-icon-btn-sm" [disabled]="page === 1" (click)="prevPage()">
                <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['chevL']"/></svg>
              </button>
              <span>Page {{ page }} / {{ totalPages }}</span>
              <button class="adm-icon-btn adm-icon-btn-sm" [disabled]="page === totalPages" (click)="nextPage()">
                <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['chevR']"/></svg>
              </button>
            </div>
          </footer>
        </section>
      </ng-container>

      <!-- ===== SEND NOTIFICATION ===== -->
      <ng-container *ngIf="activeSection === 'send'">
        <div class="adm-page-head">
          <div>
            <h1>Send notification</h1>
            <p class="adm-muted">Push a message to your members' notification inbox.</p>
          </div>
        </div>

        <div class="adm-grid-send">
          <section class="adm-card">
            <label class="adm-field">
              <span>Message</span>
              <textarea [(ngModel)]="notifMessage" name="notifMessage" rows="5" maxlength="500" placeholder="Write your announcement…"></textarea>
              <small class="adm-muted adm-right">{{ notifMessage.length }} / 500</small>
            </label>

            <div class="adm-field">
              <span>Audience</span>
              <div class="adm-seg">
                <label [class.adm-seg-on]="notifAudience === 'all'">
                  <input type="radio" name="aud" value="all" [(ngModel)]="notifAudience" /> All users ({{ notifUsers.length }})
                </label>
                <label [class.adm-seg-on]="notifAudience === 'selected'">
                  <input type="radio" name="aud" value="selected" [(ngModel)]="notifAudience" /> Selected ({{ notifSelected.size }})
                </label>
              </div>
            </div>

            <div class="adm-pick" *ngIf="notifAudience === 'selected'">
              <label *ngFor="let u of notifUsers" class="adm-pick-row">
                <input type="checkbox" [checked]="notifSelected.has(u.id)" (change)="toggleNotifUser(u.id)" />
                <div class="adm-avatar adm-avatar-sm" [style.--h]="hue(u.name)">{{ initials(u.name) }}</div>
                <div class="adm-list-main"><strong>{{ u.name }}</strong><small>{{ u.email }}</small></div>
              </label>
            </div>

            <p class="adm-info" *ngIf="notifInfo">{{ notifInfo }}</p>
            <div class="adm-form-actions">
              <button class="adm-btn adm-btn-primary" [disabled]="notifSending" (click)="sendNotification()">
                <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['send']"/></svg>
                {{ notifSending ? 'Sending…' : 'Send notification' }}
              </button>
            </div>
          </section>

          <aside class="adm-card adm-preview">
            <h4>Preview</h4>
            <div class="adm-phone-notif">
              <div class="adm-brand-mark adm-brand-mark-sm">E</div>
              <div>
                <strong>EOS Fitness</strong>
                <p>{{ notifMessage || 'Your message will appear here.' }}</p>
              </div>
            </div>
          </aside>
        </div>
      </ng-container>

      <!-- ===== APPROVALS ===== -->
      <ng-container *ngIf="activeSection === 'approvals'">
        <div class="adm-page-head">
          <div>
            <h1>Pending approvals</h1>
            <p class="adm-muted">{{ pendingApprovals.length }} request{{ pendingApprovals.length === 1 ? '' : 's' }} awaiting review</p>
          </div>
        </div>

        <section class="adm-card adm-card-flush">
          <div class="adm-loading" *ngIf="approvalsLoading"><span class="adm-spinner"></span> Loading…</div>

          <div class="adm-table-wrap" *ngIf="!approvalsLoading && pendingApprovals.length">
            <table class="adm-table">
              <thead>
                <tr><th>Member</th><th>Phone</th><th>Category</th><th>Plan</th><th>Price</th><th>Requested</th><th class="adm-th-actions"></th></tr>
              </thead>
              <tbody>
                <tr *ngFor="let row of pendingApprovals">
                  <td>
                    <div class="adm-cell-user">
                      <div class="adm-avatar adm-avatar-sm" [style.--h]="hue(row.name)">{{ initials(row.name) }}</div>
                      <div class="adm-stack"><strong>{{ row.name }}</strong><small>{{ row.email }}</small></div>
                    </div>
                  </td>
                  <td class="adm-nowrap">{{ row.phone }}</td>
                  <td><span class="adm-badge" data-tone="blue">{{ row.preferred_category }}</span></td>
                  <td>{{ row.plan_name }} <small class="adm-muted">({{ row.duration_months }} mo)</small></td>
                  <td class="adm-nowrap"><b>{{ row.price }}</b> TND</td>
                  <td class="adm-nowrap">{{ row.requested_at | date:'MMM d, HH:mm' }}</td>
                  <td class="adm-row-actions">
                    <button class="adm-btn-sm adm-btn-success" (click)="approveUser(row)">Approve</button>
                    <button class="adm-btn-sm adm-btn-danger-o" (click)="rejectUser(row)">Reject</button>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <div class="adm-empty" *ngIf="!approvalsLoading && !pendingApprovals.length">
            <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['check']"/></svg>
            <h4>All caught up</h4>
            <p class="adm-muted">There are no pending requests right now.</p>
          </div>
        </section>
      </ng-container>
    </main>
  </div>

  <!-- ============ MODAL ============ -->
  <div class="adm-modal-backdrop" *ngIf="showForm" (click)="cancelForm()">
    <div class="adm-modal" (click)="$event.stopPropagation()">
      <div class="adm-modal-head">
        <h3>{{ editingId ? 'Edit' : 'Add' }} {{ active.title.slice(0, -1) }}</h3>
        <button class="adm-icon-btn adm-icon-btn-sm" type="button" (click)="cancelForm()">
          <svg class="adm-ic" viewBox="0 0 24 24"><path [attr.d]="icons['close']"/></svg>
        </button>
      </div>
      <form (ngSubmit)="save()">
        <div class="adm-modal-body">
          <label *ngFor="let f of active.fields" class="adm-field" [class.adm-field-check]="f.type === 'checkbox'">
            <span>{{ f.label }}</span>
            <select *ngIf="f.type === 'select'" [(ngModel)]="formModel[f.key]" [name]="f.key">
              <option *ngFor="let o of f.options" [value]="o">{{ o || '— None —' }}</option>
            </select>
            <input *ngIf="f.type === 'checkbox'" type="checkbox" [(ngModel)]="formModel[f.key]" [name]="f.key" />
            <textarea *ngIf="f.type === 'textarea'" [(ngModel)]="formModel[f.key]" [name]="f.key" rows="3"></textarea>
            <ng-container *ngIf="f.type === 'image'">
              <img *ngIf="formModel[f.key + '_url']" [src]="formModel[f.key + '_url']" class="adm-file-preview" />
              <input type="file" accept="image/*" [name]="f.key" (change)="onFileChange($event, f.key)" />
            </ng-container>
            <input *ngIf="!f.type || (f.type !== 'select' && f.type !== 'checkbox' && f.type !== 'textarea' && f.type !== 'image')"
                   [type]="f.type || 'text'" [(ngModel)]="formModel[f.key]" [name]="f.key" />
          </label>
        </div>
        <div class="adm-modal-actions">
          <button type="button" class="adm-btn adm-btn-ghost" (click)="cancelForm()">Cancel</button>
          <button type="submit" class="adm-btn adm-btn-primary">Save changes</button>
        </div>
      </form>
    </div>
  </div>
</div>
